    'أمسك المقبض بكلتا اليدين ومدّ ذراعيك بالكامل فوق صدرك. تكون اليدان على خط مستقيم مع البكرة، وإلا فاضبط البكرة لأعلى أو لأسفل حتى تصير كذلك.',
