    'اضغط المنصة برفع الكعبين مع الزفير، بمدّ الكاحلين لأعلى ما يمكن وشدّ السمانة. أبقِ الركبة ثابتة طوال الوقت، ولا تثنِها في أي لحظة. اثبت في وضع الانقباض لثانية قبل بدء النزول.',
