    'ثم اثنِ المرفق مع ثبات العضد، فيصبح الساعد موازيًا للأرض وعموديًا على جذعك، أي أمامك مباشرة. يبقى العضد ثابتًا بجانب جذعك وموازيًا للأرض ومتحاذيًا مع الجذع طوال الوقت. هذه وضعية البداية.',
