    'ثبّت الجذع، وارفع مرفقيك وابدأ بثنيهما مع سحب الحبل نحو رقبتك والزفير. يبقى العضدان موازيين للأرض طوال الحركة. واصل حتى تقترب اليدان من أذنيك، ولن يوازي الساعدان الأرض في نهاية الحركة لأنهما يميلان قليلًا للأعلى، والمرفقان بعيدان عن الجانبين.',
