    'ضع القدمين بعرض الوركين، واسحب الكابل إلى صدرك وأمسك المقبض باليد الأخرى. تكون اليدان على المقبض في هذه اللحظة.',
    'واجه الأمام، وادفع الكابل بعيدًا عن صدرك. يكون الجذع مشدودًا ومشتغلًا.',
