    'ارفع مقبض البار ببطء مع الشهيق حتى يحاذي صدرك. يتحرك الساعدان فقط، ويبقى المرفقان والعضدان ثابتين بجانبك طوال الوقت.',
    'ثم ابدأ بإنزال بار الكابل إلى وضعية البداية مع الزفير وشدّ الترايسبس بقوة.',
