    'مع الشهيق، انزل ببطء حتى تشعر بالبار على منتصف صدرك. بخلاف البنش برس المعتاد، أبقِ المرفقين قريبين من الجذع طوال الوقت لتركيز العمل على الترايسبس.',
    'بعد توقف لثانية، أعد البار إلى وضعية البداية مع الزفير وادفعه بعضلات الترايسبس. مدّ ذراعيك في وضع الانقباض، واثبت لثانية ثم ابدأ النزول ببطء مجددًا. يُفضّل أن يستغرق النزول ضعف وقت الصعود على الأقل.',
