    'مع الزفير اسحب البار لأعلى مع إبقاء المرفقين قريبين من جسمك، إما إلى صدرك لاستهداف أعلى منتصف الظهر، أو إلى معدتك إذا كان هدفك عضلات الظهر العريضة.',
