    'مع إبقاء الجذع ثابتًا، اسحب المقبضين نحو جذعك مع إبقاء الذراعين قريبتين منه حتى تلامس البطن. ازفر أثناء هذه الحركة. عند تلك النقطة شدّ عضلات الظهر بقوة. اثبت عند الانقباض لثانية ثم عد ببطء إلى الوضعية الأصلية مع الشهيق.',
    'كرّر بعدد التكرارات المطلوب.',
