    'ارفع ذراعيك بقوة عندما تسحب الركبة اليمنى، واحرص أن تتحرك الركبة لأعلى ولأسفل مباشرة. تجنّب إدارة قدميك وأنت تتحرك، وواصل النظر للأمام وأنت تتحرك جانبًا.',
