    'تأكد أن تُكمل متابعة الرمية، مستعدًا لاستقبال ارتدادها. إذا كنت ترمي نحو الجدار، فتأكد أن تقف قريبًا منه بما يكفي لاستقبال الارتداد، ووجّه الرمية أعلى قليلًا مما تفعل مع شريك.',
