    'اهبط على الصندوق والركبتان مثنيتان، ممتصًا الصدمة بالرجلين. يمكنك القفز من الصندوق عائدًا إلى الأرض، ويُفضَّل أن تنزل خطوة بخطوة برجل بعد الأخرى.',
